<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="referrer" content="no-referrer"><title>SeaPass assistant</title><link rel="stylesheet" href="/css/tokens.css?v={{ filemtime(public_path('css/tokens.css')) }}"><link rel="stylesheet" href="/css/assistant.css?v={{ filemtime(public_path('css/assistant.css')) }}"><style>body{margin:0;background:var(--canvas);color:var(--text)}#sp-assistant{position:fixed;inset:0;width:100%;max-width:none;height:100dvh;border:0;border-radius:0;box-shadow:none}#sp-assistant-launch{display:none}.sp-assistant nav{padding:7px}.sp-assistant header{padding:12px 14px}#sp-guide{bottom:20px}#sp-assistant-form{padding-bottom:max(10px,env(safe-area-inset-bottom))}</style></head><body>
<button id="sp-assistant-launch" hidden></button>
<section class="sp-assistant" id="sp-assistant" role="dialog" aria-label="SeaPass assistant" data-embed="true" data-endpoint="/api/assistant" data-user="pending" data-csrf="">
<header><div><strong id="sp-assistant-title">SeaPass assistant</strong><small id="sp-assistant-state">Connecting your account…</small></div><button type="button" data-sp="close" aria-label="Close assistant">×</button></header>
<nav aria-label="Conversation controls"><button type="button" data-sp="new">New chat</button><button type="button" data-sp="history">History</button><button type="button" data-sp="tour">Show me this page</button></nav>
<div id="sp-assistant-history" hidden></div><div id="sp-assistant-messages" class="sp-assistant-messages" role="log" aria-live="polite"></div><div id="sp-assistant-notice" role="status"></div><div id="sp-assistant-files"></div>
<form id="sp-assistant-form"><label class="sp-sr-only" for="sp-assistant-input">Message SeaPass assistant</label><textarea id="sp-assistant-input" rows="2" placeholder="What would you like to do?" maxlength="12000" required></textarea><div class="sp-assistant-compose"><label class="sp-attachment" title="Attach image, PDF or text">＋<input id="sp-assistant-file" type="file" accept="image/jpeg,image/png,image/webp,application/pdf,text/plain" multiple></label><button type="button" data-sp="voice" aria-pressed="false">Voice</button><button type="submit" id="sp-assistant-send">Send</button></div></form><footer>AI can make mistakes. Confirm important travel and payment details.</footer></section>
<div id="sp-guide" hidden role="dialog"><strong id="sp-guide-title"></strong><p></p><button type="button" data-guide="next">Next</button><button type="button" data-guide="close">Done</button></div>
<script type="module" src="/js/assistant.js?v={{ filemtime(public_path('js/assistant.js')) }}"></script></body></html>
